// The function execution environment keeps track of:
// name        → "John"
// message     → "Hello"
// outer scope → global environment

const globalValue = "Global";

function outer() {
  const outerValue = "Outer";

  function inner() {
    const innerValue = "Inner";

    console.log(innerValue); // Current scope
    console.log(outerValue); // Outer scope
    console.log(globalValue); // Global scope
  }

  inner();
}

outer();

// Scope determines what variables inner() can access.
// Execution contexts provide the environment in which
// outer() and inner() execute.
